def correct_bracketing(brackets: str) -> bool:
    """Return True if every opening bracket has a corresponding closing bracket."""
    depth = 0                       # current nesting level
    for ch in brackets:
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth < 0:          # closed before any open
                return False
        # ignore any other characters silently (none expected per spec)
    return depth == 0               # all opens must have been closed

def is_happy(s):
    """Check if a string is happy:
    - Length is at least 3
    - Every 3 consecutive letters are distinct
    """
    if len(s) < 3:
        return False
    for i in range(len(s) - 2):
        window = {s[i], s[i + 1], s[i + 2]}
        if len(window) < 3:  # Not all three characters are distinct
            return False
    return True

