def get_closest_vowel(word):
    """Find the closest vowel between two consonants, searching from the right."""
    vowels = set('aeiouAEIOU')

    # Scan from right to left (skip first and last characters)
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels:
            prev_ch = word[i - 1]
            next_ch = word[i + 1]
            # Both neighbors must be consonants (alphabetic, non-vowel)
            if prev_ch.isalpha() and prev_ch not in vowels:
                if next_ch.isalpha() and next_ch not in vowels:
                    return word[i]

    return ""

